use parth_db::exec::{execute, execute_script, Outcome}; use parth_db::Database;

fn dir(name: &str) -> std::path::PathBuf { std::env::temp_dir().join(format!("pdb_ar_{}_{}", name, std::process::id())) }

fn seed(db: &Database) { execute(db, "CREATE TABLE t (id INT PRIMARY KEY, g TEXT, v INT)").unwrap(); execute(db, "INSERT INTO t VALUES (1, 'a', 1), (2, 'a', 2), (3, 'a', 3), (4, 'b', 10), (5, 'c', NULL), (6, 'c', NULL)").unwrap(); }

fn rows(db: &Database, sql: &str) -> Vec<String> { execute(db, sql).unwrap().rows.iter().map(|row| format!("{:?}", row)).collect() }

const QUERIES: [&str; 5] = ["SELECT g FROM t GROUP BY g HAVING COUNT(*) > 1 ORDER BY g", "SELECT g, SUM(v) FROM t GROUP BY g HAVING SUM(v) > 5 ORDER BY g", "SELECT DISTINCT g FROM t ORDER BY g", "SELECT g FROM t GROUP BY g HAVING COUNT(DISTINCT v) = 0", "SELECT COUNT(*), MIN(g), MAX(v) FROM t"];
#[test] fn aggregate_queries_match_after_reopen() { let d = dir("reopen"); let _ = std::fs::remove_dir_all(&d); let before: Vec<Vec<String>>; { let db = Database::open(&d).unwrap(); seed(&db); before = QUERIES.iter().map(|q| rows(&db, q)).collect(); } let db = Database::open(&d).unwrap(); let after: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); assert_eq!(before, after); let lens: Vec<usize> = after.iter().map(|r| r.len()).collect(); assert_eq!(lens, vec![2, 2, 3, 1, 1]); let _ = std::fs::remove_dir_all(&d); }
#[test] fn rolled_back_writes_never_reach_aggregates_or_reopen() { let d = dir("rollback"); let _ = std::fs::remove_dir_all(&d); let db = Database::open(&d).unwrap(); seed(&db); let before: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); match execute_script(&db, "BEGIN; INSERT INTO t VALUES (7, 'b', 20); SELECT g FROM t GROUP BY g HAVING COUNT(*) > 1 ORDER BY g; ROLLBACK").unwrap() { Outcome::Transaction { committed, results } => { assert!(!committed); assert_eq!(results[1].rows.len(), 3); } Outcome::Single(_) => panic!("expected a transaction") } let same: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); assert_eq!(before, same); drop(db); let db = Database::open(&d).unwrap(); let reopened: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); assert_eq!(before, reopened); let _ = std::fs::remove_dir_all(&d); }
#[test] fn committed_writes_reach_aggregates_after_reopen() { let d = dir("commit"); let _ = std::fs::remove_dir_all(&d); let db = Database::open(&d).unwrap(); seed(&db); match execute_script(&db, "BEGIN; INSERT INTO t VALUES (7, 'b', 20); COMMIT").unwrap() { Outcome::Transaction { committed, .. } => assert!(committed), Outcome::Single(_) => panic!("expected a transaction") } let before: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); let lens: Vec<usize> = before.iter().map(|r| r.len()).collect(); assert_eq!(lens, vec![3, 2, 3, 1, 1]); drop(db); let db = Database::open(&d).unwrap(); let after: Vec<Vec<String>> = QUERIES.iter().map(|q| rows(&db, q)).collect(); assert_eq!(before, after); assert_eq!(rows(&db, "SELECT g FROM t GROUP BY g HAVING COUNT(*) > 2").len(), 1); let _ = std::fs::remove_dir_all(&d); }